class BookListView(generics.GenericAPIView):
    queryset = Book.objects.all()
    serializer_class = BookSerializer

    def get(self, request):
        queryset = self.get_queryset()           # QuerySet
        queryset = self.filter_queryset(queryset) # فیلترها

        page = self.paginate_queryset(queryset)
        if page is not None:
            serializer = self.get_serializer(page, many=True)
            return self.get_paginated_response(serializer.data)

        serializer = self.get_serializer(queryset, many=True)
        return Response(serializer.data)

    def post(self, request):
        serializer = self.get_serializer(data=request.data)
        serializer.is_valid(raise_exception=True)
        serializer.save()
        return Response(serializer.data, status=201)

class MyBookListView(generics.ListAPIView):
    serializer_class = BookSerializer

    def get_queryset(self):
        user = self.request.user
        if user.is_staff:
            return Book.objects.all()
        return Book.objects.filter(owner=user, is_active=True)


class PublishedBookListView(generics.ListAPIView):
    serializer_class = BookSerializer

    def get_queryset(self):
        qs = Book.objects.filter(is_active=True)
        author_id = self.request.query_params.get("author")
        if author_id:
            qs = qs.filter(author_id=author_id)
        return qs.select_related("author")

class BookView(generics.GenericAPIView):
    queryset = Book.objects.all()

    def get_serializer_class(self):
        if self.request.method == "GET":
            return BookReadSerializer
        return BookWriteSerializer

    def get(self, request, pk):
        book = self.get_object()
        serializer = self.get_serializer(book)
        return Response(serializer.data)

    def put(self, request, pk):
        book = self.get_object()
        serializer = self.get_serializer(book, data=request.data)
        serializer.is_valid(raise_exception=True)
        serializer.save()
        return Response(serializer.data)

class BookDetailView(generics.RetrieveAPIView):
    queryset = Book.objects.all()
    serializer_class = BookSerializer
    lookup_field = "slug"

    def get(self, request, *args, **kwargs):
        book = self.get_object()   # با slug پیدا می‌کند
        serializer = self.get_serializer(book)
        return Response(serializer.data)

